export async function execute(args = {}) {
  const groups = {}
  for (const r of args.rows || []) groups[r.group] = (groups[r.group] || 0) + 1
  return { groups }
}

import test from 'node:test'
import assert from 'node:assert'
import { execute } from '../lib/impl.js'
test('group', async () => {
  const r = await execute({ rows: [{ group: 'a' }, { group: 'a' }, { group: 'b' }] })
  assert.deepEqual(r.groups, { a: 2, b: 1 })
})
